// phone-form.component.ts
@Component({...})
export class PhoneFormComponent {
  form = this.fb.group({
    name: ['', Validators.required],
    phoneNumbers: this.fb.array([])
  });

  get phoneNumbers(): FormArray {
    return this.form.get('phoneNumbers') as FormArray;
  }

  constructor(private fb: FormBuilder) {}

  addPhone() {
    this.phoneNumbers.push(this.fb.group({
      type: ['Home'],
      number: ['', [Validators.required, Validators.pattern(/^\d+$/)]]
    }));
  }

  removePhone(index: number) {
    this.phoneNumbers.removeAt(index);
  }

  onSubmit() {
    console.log(this.form.value);
  }
}

// phone-form.component.html
<form [formGroup]="form" (ngSubmit)="onSubmit()">
  <input formControlName="name" placeholder="Your name">

  <div formArrayName="phoneNumbers">
    <div *ngFor="let phone of phoneNumbers.controls; let i = index" [formGroupName]="i">
      <select formControlName="type">
        <option>Home</option>
        <option>Work</option>
        <option>Mobile</option>
      </select>
      <input formControlName="number" placeholder="Number">
      <button type="button" (click)="removePhone(i)">Remove</button>
      <div *ngIf="phone.get('number')?.invalid && phone.get('number')?.touched">
        Valid digits required.
      </div>
    </div>
  </div>

  <button type="button" (click)="addPhone()">Add Phone</button>
  <button type="submit" [disabled]="!form.valid">Submit</button>
</form>

<pre>{{ form.value | json }}</pre>
